select 'canon-ve-travel-standard', 'Vegans Explore Travel and Global Tour: the standard', 'brand', 'canonical', $wr${"standard": "Listed on merit. Booked the way that is best for the place. Every paid link labelled. Data for destinations.", "selection": "Selection cannot be bought: a written rubric, reviewers who never see sponsor, bureau or hotel contracts; paid money buys labelled visibility, never a listing or the approved mark.", "booking_order": "(1) the business's own booking site with our partner code (Partner link), (2) their website, (3) Booking.com through Travelpayouts labelled Paid link at the button, only when there is no direct option.", "booking_com": "Links on our website only, never in email, social, video, the podcast, the app, coupons or paid search. Never Drive or site-wide link switching. Account LESARUSS (contact@lesaruss.com), one project per brand site.", "global_tour": "2027 pilot: one co-branded Europe departure in September 2027 (Asia 2028), operated by a licensed tour operator as seller of record who holds all traveler money; a dedicated Vegans Explore host; Sean joins some dinners and his LESARUSS travel is on its own budget; Vegans Explore's share paid after departure.", "bureaus": "Home first (Visit Lauderdale, Greater Miami CVB), in-kind first; pitch FY2028 February to May 2027 with 90 days of data (ve_travel_report).", "never": "No paid placement, no tax-deductible sponsorship claims.", "source": "Sean, 2026-11-11: \"Go with your recommendations, lock it into the playbook.\" Playbook ve-travel."}$wr$::jsonb, 'active', 'sar', false, 20, array['vegans-explore','travel','global-tour','affiliate','canon'], 1, 'Locked by Sean 2026-11-11 (playbook ve-travel).', 'V', 'Logan'
where not exists (select 1 from knowledge_records where slug='canon-ve-travel-standard');
insert into playbook_records (slug, brand_slug, author, body, source, kind)
select 've-travel', 'vegans-explore', 'Logan', $wr$Wrapped 2026-11-12 (Sean: "Let's wrap this up"). Canon canon-ve-travel-standard and canon-ve-web-reader; handoff docs/handoff/2026-11-12-ve-travel.md. Next action: when Sean sends the Beck Hall Booking.com link, make the travel-booking /go/ links, switch on Beck Hall only, prove it live and show Sean. Waiting on Sean: the three drafts, the Booking.com approval, the tax-deductible line in the Google Doc and Issuu deck, the homepage nonprofit line.$wr$, 'text', 'edit'
where not exists (select 1 from playbook_records where slug='ve-travel' and body like 'Wrapped 2026-11-12%');
insert into brief_checkpoints (brand_slug, station, account, status, summary, files_touched, next_step, session_label, open_items, handoff_url)
select 'vegans-explore', 'logan', 'claude-code', 'handed_off', $wr$Vegans Explore Travel: Travel door (5 sections), 20 Travel listings live (8 cruises, 12 stays), ve-web-reader, Travelpayouts research and the Vegansexplore project (Booking.com applied), the Book card (direct partner then Booking.com, labelled, website only, inactive until a link exists), BOSS and a five-seat panel, playbook ve-travel locked (Global Tour pilot September 2027 via a licensed operator), ve_travel_report, three first-contact drafts. All on main.$wr$, $wr$["directory/listing.html", "public/ve-region-directory.js", "public/ve-listing-admin.js", "admin/depot/directory-review.html", "claim.html", "directory/index.html", "supabase/functions/ve-web-reader/index.ts", "supabase/functions/ve-menu-reader/index.ts", "supabase/functions/ve-claims/index.ts", "supabase/migrations/20261111_*", "docs/proposals/2026-11-11-*", "docs/outreach/2026-11-11-ve-travel-first-contacts.md", "docs/handoff/2026-11-12-ve-travel.md", "CLAUDE.md"]$wr$::jsonb,
 $wr$When Sean sends the Beck Hall Booking.com link: make travel-booking /go/ links, set book_link_code on Beck Hall only, prove live at 1440 and 390, show Sean.$wr$, 've-travel', $wr$["Sean: approve the three drafts (docs/outreach/2026-11-11-ve-travel-first-contacts.md)", "Sean: Booking.com approval, then one Beck Hall link", "Sean: remove Tax-Deductible Sponsorship from the Google Doc and Issuu deck", "Sean: homepage nonprofit line", "Unproven live: ve-web-reader cross-host redirect into a private address"]$wr$::jsonb, $wr$https://github.com/lesaruss/vegansexplore-com/blob/main/docs/handoff/2026-11-12-ve-travel.md$wr$
